-- Human resources in PostgreSQL: two self-referencing hierarchies (departments and
-- managers), a CHECK relating two columns, a history keyed by employee and date, and
-- a generated column.

CREATE TYPE employment_kind AS ENUM ('full_time', 'part_time', 'contractor');

CREATE TABLE departments (
    department_id        smallint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name                 varchar(80) NOT NULL UNIQUE,
    cost_center          varchar(10) NOT NULL UNIQUE,
    parent_department_id smallint REFERENCES departments (department_id)
);

CREATE TABLE job_titles (
    job_title_id integer PRIMARY KEY,
    title        varchar(80) NOT NULL,
    min_salary   numeric(10, 2) NOT NULL,
    max_salary   numeric(10, 2) NOT NULL,
    CONSTRAINT ck_salary_band CHECK (min_salary > 0 AND max_salary > min_salary)
);

CREATE TABLE employees (
    employee_id   integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email         varchar(120) NOT NULL UNIQUE,
    first_name    text NOT NULL,
    last_name     text NOT NULL,
    birth_date    date NOT NULL CHECK (birth_date < DATE '2008-01-01'),
    hired_on      date NOT NULL,
    left_on       date,
    kind          employment_kind NOT NULL,
    department_id smallint NOT NULL REFERENCES departments,
    job_title_id  integer NOT NULL REFERENCES job_titles,
    manager_id    integer REFERENCES employees (employee_id),
    salary        numeric(10, 2) NOT NULL CHECK (salary > 0),
    full_name     text GENERATED ALWAYS AS (first_name || ' ' || last_name) STORED,
    CONSTRAINT ck_left CHECK (left_on IS NULL OR left_on > hired_on)
);

CREATE TABLE salary_history (
    employee_id integer NOT NULL REFERENCES employees ON DELETE CASCADE,
    valid_from  date NOT NULL,
    salary      numeric(10, 2) NOT NULL CHECK (salary > 0),
    reason      text,
    PRIMARY KEY (employee_id, valid_from)
);

CREATE TABLE timesheets (
    timesheet_id bigserial PRIMARY KEY,
    employee_id  integer NOT NULL REFERENCES employees,
    work_date    date NOT NULL,
    hours        numeric(4, 2) NOT NULL CHECK (hours > 0 AND hours <= 24),
    project_code varchar(12) NOT NULL,
    approved     boolean NOT NULL DEFAULT false
);

CREATE INDEX timesheets_by_day ON timesheets (work_date, employee_id);

CREATE FUNCTION department_headcount(d smallint) RETURNS bigint LANGUAGE sql STABLE AS $$
    SELECT count(*) FROM employees WHERE department_id = d;
$$;

CREATE TRIGGER no_op_on_update BEFORE UPDATE ON timesheets FOR EACH ROW EXECUTE FUNCTION suppress_redundant_updates_trigger();
